-- Files and folders use one independent per-entry access policy.
DO $entry_kind_contract$
DECLARE expected text; matching text[];
BEGIN
    -- Parse the exact prior V925 expression with PostgreSQL itself. Constraint names were
    -- generated by PostgreSQL, so match the authoritative expression, never a broad substring.
    CREATE TEMP TABLE company_file_entry_kind_contract (
        kind text, attachment_id uuid, pending boolean, size_bytes bigint, password_hash text,
        CHECK((kind='FOLDER' AND attachment_id IS NULL AND NOT pending AND size_bytes IS NULL)
           OR (kind='FILE' AND password_hash IS NULL AND (pending OR attachment_id IS NOT NULL)))
    ) ON COMMIT DROP;
    SELECT pg_get_expr(conbin,conrelid) INTO STRICT expected FROM pg_constraint
        WHERE conrelid='pg_temp.company_file_entry_kind_contract'::regclass AND contype='c';
    SELECT array_agg(conname ORDER BY conname) INTO matching FROM pg_constraint
        WHERE conrelid='public.company_file_nodes'::regclass AND contype='c'
          AND pg_get_expr(conbin,conrelid)=expected;
    IF cardinality(matching) IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION 'Unreviewed company file kind-state constraint; access upgrade refused' USING ERRCODE='23514';
    END IF;
    EXECUTE format('ALTER TABLE public.company_file_nodes DROP CONSTRAINT %I',matching[1]);
    ALTER TABLE public.company_file_nodes ADD CONSTRAINT company_file_nodes_kind_state_check
        CHECK((kind='FOLDER' AND attachment_id IS NULL AND NOT pending AND size_bytes IS NULL)
           OR (kind='FILE' AND (pending OR attachment_id IS NOT NULL)));
END $entry_kind_contract$;

-- Make the library entrance independently revocable by department. Preserve the
-- current default visibility through explicit, local department allocations only
-- when the old whole-company baseline is still enabled. Never invent personal
-- overrides. Existing parent-department inheritance stays authoritative: revoke
-- the actual contributing allocations (or apply the normal individual revoke).
INSERT INTO department_permissions(department_id,permission_id)
SELECT department.id,permission.id
FROM departments department CROSS JOIN permissions permission
WHERE NOT department.is_deleted AND permission.code='company_file:view' AND permission.baseline
ON CONFLICT DO NOTHING;
UPDATE permissions SET baseline=false WHERE code='company_file:view' AND baseline;

UPDATE permissions SET name='查看公司资料库',
    description='显示资料库入口并查看获授权文件或文件夹的元信息；资料自身的人员、部门及密码范围独立设置。'
    WHERE code='company_file:view';
UPDATE permissions SET name='管理公司资料访问设置',
    description='管理现有文件和文件夹的独立可见范围及访问密码，不修改任何系统权限授权；需本人登录密码再认证。'
    WHERE code='company_file:manage_permissions';
UPDATE permissions SET description='在授权目录新建文件夹，可同时设置新文件夹的初始阅读范围与访问密码。'
    WHERE code='company_file:create';
UPDATE permissions SET description='在授权目录上传新文件，可同时设置初始阅读范围与访问密码；原件仍须通过统一安全扫描。'
    WHERE code='company_file:upload';
